33:export default function planMode(pi: ExtensionAPI) {
34:  // ─── Saved tool list for restoring ────────────────────────────────────────
35:  let savedToolNames: string[] | null = null;
36:
37:  function saveAndSetActiveTools(toolNames: string[]): void {
38:    if (savedToolNames === null) {
39:      savedToolNames = pi.getAllTools().map((t) => t.name);
40:    }
41:    pi.setActiveTools(toolNames);
42:  }
43:
44:  /** Tool names from the registry, excluding plan_complete (only available in execute mode). */
45:  function toolsWithoutPlanComplete(names: string[]): string[] {
46:    return names.filter((n) => n !== "plan_complete");
47:  }
48:
49:  function restoreAllTools(): void {
50:    if (savedToolNames !== null) {
51:      pi.setActiveTools(toolsWithoutPlanComplete(savedToolNames));
52:      savedToolNames = null;
53:    } else {
54:      pi.setActiveTools(toolsWithoutPlanComplete(pi.getAllTools().map((t) => t.name)));
55:    }
56:  }
57:
58:  /** Get absolute path to the active plan file, or null if none set. */
59:  function getPlanFilePath(): string | null {
60:    const file = getActivePlanFile();
61:    if (!file) return null;
62:    return join(process.cwd(), PLAN_DIR, file);
63:  }
64:
65:  /** Get a display title for the active plan.
66:   *  Tries # Plan: heading from file, falls back to titleFromFilename. */
67:  function getPlanDisplayTitle(): string | null {
68:    const file = getActivePlanFile();
69:    if (!file) return null;
70:    const filePath = getPlanFilePath();
71:    if (filePath && existsSync(filePath)) {
72:      const heading = readFileSync(filePath, "utf-8").match(/^# Plan:\s*(.+)$/m);
73:      if (heading) return heading[1].trim();
74:    }
75:    return titleFromFilename(file);
76:  }
77:
78:  // ─── UI helpers ────────────────────────────────────────────────────────────
79:
80:  function updateStatus(ctx: ExtensionContext): void {
81:    if (!ctx.hasUI) return;
82:    const mode = getMode();
83:
84:    if (mode === "plan") {
85:      const title = getPlanDisplayTitle();
86:      const widgetText = title
87:        ? USER_CONFIG.labels.plan.widgetWithTitle.replace("{title}", title)
88:        : USER_CONFIG.labels.plan.widget;
89:      ctx.ui.setWidget("plan-mode", USER_CONFIG.ui.hideWidget ? undefined : [applyLabelColor(ctx.ui.theme, USER_CONFIG.labels.plan.widgetColor, widgetText)]);
90:    } else if (mode === "execute") {
91:      const title = getPlanDisplayTitle();
92:      const widgetText = title
93:        ? USER_CONFIG.labels.execute.widgetWithTitle.replace("{title}", title)
94:        : USER_CONFIG.labels.execute.widget;
95:      ctx.ui.setWidget("plan-mode", USER_CONFIG.ui.hideWidget ? undefined : [applyLabelColor(ctx.ui.theme, USER_CONFIG.labels.execute.widgetColor, widgetText)]);
96:    } else {
97:      ctx.ui.setWidget("plan-mode", undefined);
98:    }
99:
100:    pi.events.emit("plan-mode:state", { mode });
101:  }
102:
103:  // ─── State transitions ─────────────────────────────────────────────────────
104:
105:  /** Mutual-exclusion guard: chat + plan cannot co-activate (undefined = chat-mode ext not loaded = allowed). Returns true if chat is active (caller must abort). */
106:  function chatActive(ctx: ExtensionContext): boolean {
107:    const chatMode = (globalThis as Record<string, unknown>).__chatMode as { mode?: string } | undefined;
108:    if (chatMode?.mode && chatMode.mode !== "off") {
109:      if (ctx.hasUI) ctx.ui.notify("Exit chat mode first", "warning");
110:      return true;
111:    }
112:    return false;
113:  }
114:
115:  function enterPlanMode(ctx: ExtensionContext): void {
116:    // Mutual-exclusion guard: chat + plan cannot co-activate
117:    if (chatActive(ctx)) return;
118:    transition("plan", pi);
119:    saveAndSetActiveTools(PLAN_MODE_TOOLS);
120:    updateStatus(ctx);
121:    if (ctx.hasUI && !USER_CONFIG.ui.hideNotify) ctx.ui.notify(USER_CONFIG.labels.plan.notify, USER_CONFIG.labels.plan.notifyType as "info" | "warning" | "error");
122:  }
123:
124:  function enterExecuteMode(ctx: ExtensionContext): void {
125:    transition("execute", pi);
126:    // Restore all tools AND include plan_complete (only available during execute mode)
127:    const baseNames = savedToolNames ?? pi.getAllTools().map((t) => t.name);
128:    pi.setActiveTools([...toolsWithoutPlanComplete(baseNames), "plan_complete"]);
129:    savedToolNames = null;
130:    updateStatus(ctx);
131:    const title = getPlanDisplayTitle();
132:    const notifyText = title
133:      ? USER_CONFIG.labels.execute.notifyWithTitle.replace("{title}", title)
134:      : USER_CONFIG.labels.execute.notify;
135:    if (ctx.hasUI && !USER_CONFIG.ui.hideNotify) ctx.ui.notify(notifyText, USER_CONFIG.labels.execute.notifyType as "info" | "warning" | "error");
136:  }
137:
138:  function enterOffMode(ctx: ExtensionContext, message?: string): void {
139:    transition("off", pi);
140:    restoreAllTools();
141:    updateStatus(ctx);
142:    if (ctx.hasUI && !USER_CONFIG.ui.hideNotify) ctx.ui.notify(
143:      message ?? USER_CONFIG.labels.off.notify,
144:      message ? "info" : (USER_CONFIG.labels.off.notifyType as "info" | "warning" | "error")
145:    );
146:  }
147:
148:  /** Cleanup plan file when transitioning off via plan_complete, if configured. */
149:  function cleanupPlanFile(): void {
150:    if (!USER_CONFIG.cleanup.cleanupOnComplete) return;
151:    const filePath = getPlanFilePath();
152:    if (filePath && existsSync(filePath)) unlinkSync(filePath);
153:    setActivePlanFile(null, pi);
154:  }
155:
156:  // ─── Re-derive state from entries on the current branch ──────────────────────
157:
158:  function syncStateFromBranch(ctx: ExtensionContext): void {
159:    const branch = ctx.sessionManager.getBranch();
160:    const restored = restore(branch);
161:
162:    if (!restored) {
163:      resetState();
164:      restoreAllTools();
165:      updateStatus(ctx);
166:      return;
167:    }
168:
169:    // Check if active plan file was deleted externally
170:    const filePath = getPlanFilePath();
171:    if (getActivePlanFile() && filePath && !existsSync(filePath)) {
172:      if (ctx.hasUI) ctx.ui.notify(`Plan file "${getActivePlanFile()}" not found — disabling plan mode.`, "warning");
173:      enterOffMode(ctx);
174:      return;
175:    }
176:
177:    if (getMode() === "plan") {
178:      saveAndSetActiveTools(PLAN_MODE_TOOLS);
179:    } else if (getMode() === "execute") {
180:      // Restore execute mode tools including plan_complete
181:      const allNames = pi.getAllTools().map((t) => t.name);
182:      pi.setActiveTools([...toolsWithoutPlanComplete(allNames), "plan_complete"]);
183:    }
184:
185:    updateStatus(ctx);
186:  }
187:
188:  // ─── Event: session_start ──────────────────────────────────────────────────
189:
190:  pi.on("session_start", async (event, ctx) => {
191:    // Handle --plan flag: start in plan mode on initial startup
192:    if (event.reason === "startup" && pi.getFlag("plan") === true && getMode() === "off") {
193:      enterPlanMode(ctx);
194:      return;
